OUT = ROOT / 'IBM_Telco_Churn_EDA_Report.pdf'
summary = json.loads((ROOT/'results/summary.json').read_text(encoding='utf-8'))

styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='CoverTitle', parent=styles['Title'], fontName='Helvetica-Bold', fontSize=25, leading=31, alignment=TA_CENTER, textColor=colors.HexColor('#123B4A'), spaceAfter=18))
